package com.lojaagro.estoque_api.entities;
import jakarta.persistence.*;import java.math.*;
@Entity@Table(name="pedido_lanchonete_adicional")
public class PedidoLanchoneteAdicional{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="pedido_item_id",nullable=false)private PedidoLanchoneteItem item;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="opcao_id",nullable=false)private OpcaoAdicional opcao;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="produto_id",nullable=false)private Produto produto;@Column(nullable=false,length=120)private String nome;@Column(nullable=false)private int quantidade=1;@Column(name="preco_unitario",nullable=false,precision=19,scale=2)private BigDecimal precoUnitario;protected PedidoLanchoneteAdicional(){}public PedidoLanchoneteAdicional(PedidoLanchoneteItem item,OpcaoAdicional opcao){this.item=item;this.opcao=opcao;this.produto=opcao.getProduto();this.nome=produto.getNome();this.precoUnitario=produto.getPreco();}public Produto getProduto(){return produto;}public String getNome(){return nome;}public int getQuantidade(){return quantidade;}public BigDecimal getPrecoUnitario(){return precoUnitario;}public OpcaoAdicional getOpcao(){return opcao;}}
